# 48_scandal_rare_event_test.R
# Rare-events break test for the financial-scandal series (Figure 3.5, Panel
# C), PJ 10 Sep: "on the break could do a rare events test" - following up
# 47_scandal_break_test.R, whose own header flagged that a mean-shift Chow
# F-test (built for smooth continuous rates) is a rough fit for a 12-event,
# 38-zero-year COUNT series.
#
# METHOD: Poisson change-point / likelihood-ratio test, the standard tool for
# a rare-events count series (this is a count of departures, not a continuous
# rate) - NOT the mean-shift Chow reused from 45/47. Same sup-statistic +
# permutation-significance ARCHITECTURE as 45/47 (search every candidate
# split year, take the peak, get a p-value by resampling), applied to a model
# actually suited to sparse counts:
#   - Pooled model:  n_scandal ~ offset(log(n_active_ministers)), Poisson
#   - Split model:   n_scandal ~ period + offset(log(n_active_ministers))
#   - LR statistic = 2*(logLik_split - logLik_pooled), chi-sq(1) under H0
#   - sup-LR = the split year maximising this, searched the same way as the
#     mean-shift Chow's sup-F (same trim/min_seg window)
#   - Significance via PERMUTATION (resample which year each event count
#     lands in, 10,000 draws) rather than trusting the asymptotic chi-sq(1),
#     since with only 12 events the asymptotics are themselves shaky - same
#     permutation-over-asymptotics preference already standing in this
#     project (e.g. the GAM nonlinearity check, 45's own Chow test).
#
# DATA: data/processed/scandal_resignations_annual_1979_2025.csv
# OUTPUT: console only - diagnostic, compared directly against 47's result.

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, readr)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT
d <- read_csv(file.path(PROJECT, "data/processed/scandal_resignations_annual_1979_2025.csv"),
              show_col_types = FALSE) |> arrange(year)

set.seed(42)
NPERM <- 10000

poisson_LR <- function(y, exposure, k, min_seg = 3) {
  n <- length(y)
  if (k < min_seg || k > n - min_seg) return(NA_real_)
  period <- factor(rep(c("pre", "post"), c(k, n - k)))
  m_pool  <- glm(y ~ 1 + offset(log(exposure)), family = poisson)
  m_split <- tryCatch(glm(y ~ period + offset(log(exposure)), family = poisson),
                       warning = function(w) NULL, error = function(e) NULL)
  if (is.null(m_split)) return(NA_real_)
  2 * (as.numeric(logLik(m_split)) - as.numeric(logLik(m_pool)))
}

.ks_interior <- function(n, trim = 0.15, min_seg = 3) {
  lo <- max(min_seg, floor(trim * n)); hi <- min(n - min_seg, n - floor(trim * n)); lo:hi
}
supLR <- function(y, exposure, year, trim = 0.15, min_seg = 3) {
  n <- length(y); ks <- .ks_interior(n, trim, min_seg)
  lr <- vapply(ks, function(k) poisson_LR(y, exposure, k, min_seg), numeric(1))
  list(peak_year = year[ks[which.max(lr)]], peak_LR = max(lr, na.rm = TRUE),
       curve = data.frame(year = year[ks], LR = lr))
}
perm_pvalue <- function(y, exposure, year, observed_LR, trim = 0.15, min_seg = 3, nperm = NPERM) {
  perm_max <- replicate(nperm, {
    ys <- sample(y)
    supLR(ys, exposure, year, trim, min_seg)$peak_LR
  })
  mean(perm_max >= observed_LR, na.rm = TRUE)
}

y <- d$n_scandal
exposure <- d$n_active_ministers
yr <- d$year

res <- supLR(y, exposure, yr)
pval <- perm_pvalue(y, exposure, yr, res$peak_LR)

cat(sprintf("N years = %d, total events = %d, exposure (active ministers) range %d-%d\n",
            length(y), sum(y), min(exposure), max(exposure)))
cat(sprintf("\n=== Poisson change-point test, n_scandal (rare-events method) ===\n"))
cat(sprintf("Peak break year: %d, LR = %.2f, permutation p = %.4f (%d draws)\n",
            res$peak_year, res$peak_LR, pval, NPERM))
cat("Top 5 candidate years by LR:\n")
print(res$curve |> arrange(desc(LR)) |> head(5))

k <- which(yr == res$peak_year)
rate_pre  <- 100 * sum(y[1:k]) / sum(exposure[1:k])
rate_post <- 100 * sum(y[(k+1):length(y)]) / sum(exposure[(k+1):length(y)])
cat(sprintf("\nPooled rate before %d: %.3f events per 100 minister-years (n=%d events, %d years)\n",
            res$peak_year, rate_pre, sum(y[1:k]), k))
cat(sprintf("Pooled rate from %d:  %.3f events per 100 minister-years (n=%d events, %d years)\n",
            res$peak_year, rate_post, sum(y[(k+1):length(y)]), length(y)-k))

cat("\n=== Comparison with 47_scandal_break_test.R's mean-shift Chow result ===\n")
cat("Chow (continuous-rate method): peak 1993, F=4.57, p=0.235 - not significant.\n")
cat("Poisson (count method): see above - the appropriate comparison for this series.\n")
